head.script:
scwin.gVar = {
    "cInvalidMessageFunc" : "",
    "cDisplaymessage" : "",
    "cFailCause" : "",
    "cInvalidMessage" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > invalidMessageFunc]<br/>입력값에 대한 유효성 체크를 통과하지 못한 경우 메시지를 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "displaymessage=true 이고 validate() 메소드의 실행 결과가 실패일때 동작합니다.",
        "메시지를 생성할 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 반환값이 새로운 메시지로 적용됩니다.",
        "사용자 정의 함수에서 값을 반환하지 않거나 빈 문자열('') 을 반환하면 메시지가 표시되지 않습니다.",
        "사용자 정의 함수에서 반환된 값은 alert() 메소드로 표시됩니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트의 렌더링 ID 를 갖는 callerId 속성을 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트를 반환하는 getCaller() 메소드를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크를 통과하지 못한 항목을 문자열로 반환하는 getType() 메소드 ('mandatory', 'maxLength', 'maxByteLength', 'minLength', 'minByteLength' 값을 가짐) 를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크를 통과하지 못한 항목의 속성값을 반환하는 getValue() 메소드를 사용할 수 있습니다.",
        "validate() 메소드는 자동으로 실행되지 않으므로 스크립트로 직접 실행해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_displaymessage.setValue("2");
    con_failCause.setValue("minlength");
    con_invalidMessageFunc.setValue("2");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트로 invalidMessageFunc 와 실패 원인 속성은 위 조건에서 선택하며, Target 재생성 시 초기값은 mandatory 선택 시 빈값으로, 그 외에는 secret (6자 / 6바이트) 으로 설정됩니다 (mandatory=true / minlength=10 / maxlength=3 / minByteLength=10 / maxByteLength=3)\n[절차] invalidMessageFunc, displaymessage, 실패 원인 속성 (필요 시 invalidMessage) 선택 -> Target 재생성 -> validate 버튼 클릭 (maxlength 는 target1 입력값을 건드리지 말고 그대로 클릭 - 직접 입력하면 maxlength 제한에 잘려 초과 값을 만들 수 없음)\n[확인] Target 재생성 직후에는 alert 이 뜨지 않고 validate 버튼을 눌러야 뜨는지, alert 창의 표시 여부와 문구 (사용자 정의 함수 반환값 / invalidMessage / 시스템 기본 메시지), 결과창의 this 멤버 값과 validate() 반환값"', '', 'label1');

    // 조건 설정
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getText();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cFailCause"] = con_failCause.getValue();
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();

    let properties = {
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessage : scwin.gVar["cInvalidMessage"],
    }

    // 유효성 체크 실패를 유발할 원인 속성 (선택한 1개만 적용)
    if (scwin.gVar["cFailCause"] === "mandatory")
        properties.mandatory = "true";
    else if (scwin.gVar["cFailCause"] === "minlength")
        properties.minlength = "10";
    else if (scwin.gVar["cFailCause"] === "maxlength")
        properties.maxlength = "3";
    else if (scwin.gVar["cFailCause"] === "minByteLength")
        properties.minByteLength = "10";
    else if (scwin.gVar["cFailCause"] === "maxByteLength")
        properties.maxByteLength = "3";

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // mandatory 원인은 값이 비어야 실패하므로 생성 직후 헬퍼가 넣은 초기값을 빈값으로 덮음 (그 외 원인은 초기값 secret 유지)
    if (scwin.gVar["cFailCause"] === "mandatory")
        target1.setValue("");
}



// validate 실행 (invalidMessageFunc 발동 수단) - validation 1 ~ 5, 10 판정 출력
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이를 함께 출력
    let nLength = (target1.getValue() || "").length;
    let rtn = target1.validate();

    let strInvalidMessageFunc = (scwin.gVar["cInvalidMessageFunc"] === "") ? "미설정" : scwin.gVar["cInvalidMessageFunc"];
    let strDisplaymessage = (scwin.gVar["cDisplaymessage"] === "") ? "미설정" : scwin.gVar["cDisplaymessage"];
    let strInvalidMessage = (scwin.gVar["cInvalidMessage"] === "") ? "미설정" : scwin.gVar["cInvalidMessage"];

    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc " + strInvalidMessageFunc + " / displaymessage " + strDisplaymessage + " / 실패 원인 " + scwin.gVar["cFailCause"] + " / invalidMessage " + strInvalidMessage + " / target1 값 길이 " + nLength + " -> validate() 반환값 : " + rtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수 (반환값 있음) - validation 6 ~ 9 판정 출력
scwin.fn_msg = function () {
    // getCaller() 는 컴포넌트 객체라 값으로 표시할 수 없으므로 target1 과의 동일 여부로 판정
    wf_body_bottom.getObj("scwin").setReturnValue("사용자 정의 함수 this -> callerId : " + this.callerId + " / getCaller() 가 target1 과 동일 : " + (this.getCaller() === target1) + " / getType() : " + this.getType() + " / getValue() : " + this.getValue());

    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ", 속성값 : " + this.getValue() + ")";
}



// 값을 반환하지 않는 사용자 정의 함수 - validation 4 판정 수단
scwin.fn_msg_noReturn = function () {
}



// 빈 문자열을 반환하는 사용자 정의 함수 - validation 4 판정 수단
scwin.fn_msg_empty = function () {
    return "";
}
